package com.vladmihalcea.phd.reservoir.util;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;

/**
 * Reshapes the tidy long-format JMH result CSVs written under {@code metrics/jmh-results/} (which is
 * git-ignored and regenerated by the benchmarks) into the chart-ready wide CSVs the gnuplot scripts
 * consume, one per paper figure under {@code metrics/<Figure>/}. This is the missing bridge between the
 * JMH families (E1-E3, E5) and the figure convention: run it after {@code run-performance-benchmarks.bat}
 * and before {@code render-charts.bat} (both {@code .bat}s call it for you).
 * <p>
 * Every transform no-ops silently when its source file is absent, so a partial benchmark run still
 * produces the figures it can.
 *
 * @author Vlad Mihalcea
 */
public final class FiguresFromJmh {

    private static final int DEFAULT_K = 1028;

    private FiguresFromJmh() {
    }

    public static void main(String[] args) {
        Path jmh = jmhResultsDir();
        System.out.println("Reading JMH results from " + jmh);
        updateCost(jmh);
        allocationRate(jmh);
        concurrency(jmh);
        batchedInsertion(jmh);
        queryCost(jmh);
        System.out.println("Figure CSVs refreshed.");
    }

    // E1: per-update cost, clustered bars per strategy grouped by k (avgt / ns).
    private static void updateCost(Path jmh) {
        List<Row> rows = readCsv(jmh.resolve("UpdateThroughputBenchmark.csv"));
        if (rows.isEmpty()) {
            return;
        }
        List<String> ks = distinct(rows, "k");
        List<String> strategies = distinct(rows, "strategy");
        Map<String, Map<String, String>> byStrategy = new LinkedHashMap<>();
        for (Row r : rows) {
            if (!"avgt".equals(r.get("mode"))) {
                continue;
            }
            byStrategy.computeIfAbsent(r.get("strategy"), s -> new LinkedHashMap<>())
                    .put(r.get("k"), r.get("score"));
        }
        String[] header = new String[ks.size() + 1];
        header[0] = "strategy";
        for (int i = 0; i < ks.size(); i++) {
            header[i + 1] = "k" + ks.get(i);
        }
        Path out = CsvWriter.metricsPath("UpdateCost", "update-cost.csv");
        try (CsvWriter w = new CsvWriter(out, header)) {
            for (String s : strategies) {
                Map<String, String> perK = byStrategy.getOrDefault(s, Map.of());
                Object[] row = new Object[ks.size() + 1];
                row[0] = s;
                for (int i = 0; i < ks.size(); i++) {
                    row[i + 1] = perK.getOrDefault(ks.get(i), "");
                }
                w.writeRow(row);
            }
        }
        System.out.println("  wrote " + out);
    }

    // E4 (allocation half): bytes allocated per update at the default k (gc.alloc.rate.norm).
    private static void allocationRate(Path jmh) {
        List<Row> rows = readCsv(jmh.resolve("UpdateThroughputBenchmark.csv"));
        if (rows.isEmpty() || !rows.get(0).has("alloc_rate_norm")) {
            return;
        }
        Path out = CsvWriter.metricsPath("AllocationRate", "alloc-rate.csv");
        boolean any = false;
        List<Object[]> outRows = new ArrayList<>();
        for (Row r : rows) {
            if (!"avgt".equals(r.get("mode")) || !String.valueOf(DEFAULT_K).equals(r.get("k"))) {
                continue;
            }
            String alloc = r.get("alloc_rate_norm");
            if (alloc == null || alloc.isBlank()) {
                continue;
            }
            any = true;
            outRows.add(new Object[]{r.get("strategy"), alloc});
        }
        if (!any) {
            return;
        }
        try (CsvWriter w = new CsvWriter(out, "strategy", "alloc_bytes_per_op")) {
            outRows.forEach(w::writeRow);
        }
        System.out.println("  wrote " + out);
    }

    // E2: threads vs. aggregate throughput, one line per strategy (reads every -tN file).
    private static void concurrency(Path jmh) {
        List<Row> all = new ArrayList<>();
        try (var stream = Files.list(jmh)) {
            for (Path p : stream.toList()) {
                String name = p.getFileName().toString();
                if (name.startsWith("ConcurrentUpdateBenchmark-t") && name.endsWith(".csv")) {
                    all.addAll(readCsv(p));
                }
            }
        } catch (IOException e) {
            return;
        }
        if (all.isEmpty()) {
            return;
        }
        List<String> strategies = distinct(all, "strategy");
        // threads column holds the actual thread count for each run.
        LinkedHashMap<Integer, Map<String, String>> byThreads = new LinkedHashMap<>();
        for (Row r : all) {
            int threads = Integer.parseInt(r.get("threads"));
            byThreads.computeIfAbsent(threads, t -> new LinkedHashMap<>())
                    .put(r.get("strategy"), r.get("score"));
        }
        List<Integer> threadCounts = new ArrayList<>(byThreads.keySet());
        threadCounts.sort(Integer::compareTo);
        String[] header = new String[strategies.size() + 1];
        header[0] = "threads";
        for (int i = 0; i < strategies.size(); i++) {
            header[i + 1] = strategies.get(i);
        }
        Path out = CsvWriter.metricsPath("Concurrency", "concurrency.csv");
        try (CsvWriter w = new CsvWriter(out, header)) {
            for (int threads : threadCounts) {
                Map<String, String> perStrategy = byThreads.get(threads);
                Object[] row = new Object[strategies.size() + 1];
                row[0] = threads;
                for (int i = 0; i < strategies.size(); i++) {
                    row[i + 1] = perStrategy.getOrDefault(strategies.get(i), "");
                }
                w.writeRow(row);
            }
        }
        System.out.println("  wrote " + out);
    }

    // E3: insertion time vs. batch size, one line per insertion method (the C4 speedup figure).
    private static void batchedInsertion(Path jmh) {
        List<Row> rows = readCsv(jmh.resolve("BatchedInsertionBenchmark.csv"));
        if (rows.isEmpty()) {
            return;
        }
        List<String> methods = distinct(rows, "benchmark");
        List<String> batchSizes = distinct(rows, "batchSize");
        Map<String, Map<String, String>> byBatch = new LinkedHashMap<>();
        for (Row r : rows) {
            byBatch.computeIfAbsent(r.get("batchSize"), b -> new LinkedHashMap<>())
                    .put(r.get("benchmark"), r.get("score"));
        }
        String[] header = new String[methods.size() + 1];
        header[0] = "batchSize";
        for (int i = 0; i < methods.size(); i++) {
            header[i + 1] = methods.get(i);
        }
        Path out = CsvWriter.metricsPath("BatchedInsertion", "batched-insertion.csv");
        try (CsvWriter w = new CsvWriter(out, header)) {
            for (String batch : batchSizes) {
                Map<String, String> perMethod = byBatch.get(batch);
                Object[] row = new Object[methods.size() + 1];
                row[0] = batch;
                for (int i = 0; i < methods.size(); i++) {
                    row[i + 1] = perMethod.getOrDefault(methods.get(i), "");
                }
                w.writeRow(row);
            }
        }
        System.out.println("  wrote " + out);
    }

    // E5: query cost per strategy (bars with error).
    private static void queryCost(Path jmh) {
        List<Row> rows = readCsv(jmh.resolve("QuantileQueryBenchmark.csv"));
        if (rows.isEmpty()) {
            return;
        }
        Path out = CsvWriter.metricsPath("QueryCost", "query-cost.csv");
        try (CsvWriter w = new CsvWriter(out, "strategy", "query_ns", "err")) {
            for (Row r : rows) {
                String err = r.get("score_error");
                w.writeRow(r.get("strategy"), r.get("score"),
                        err == null || err.isBlank() || "NaN".equals(err) ? "0" : err);
            }
        }
        System.out.println("  wrote " + out);
    }

    // -------------------------------------------------------------------------
    // Minimal CSV reader
    // -------------------------------------------------------------------------

    private static List<Row> readCsv(Path file) {
        if (!Files.exists(file)) {
            return List.of();
        }
        try (BufferedReader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
            String headerLine = reader.readLine();
            if (headerLine == null) {
                return List.of();
            }
            String[] header = headerLine.split(",", -1);
            List<Row> rows = new ArrayList<>();
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.isBlank()) {
                    continue;
                }
                String[] cells = line.split(",", -1);
                Map<String, String> map = new LinkedHashMap<>();
                for (int i = 0; i < header.length && i < cells.length; i++) {
                    map.put(header[i].trim(), cells[i].trim());
                }
                rows.add(new Row(map));
            }
            return rows;
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static List<String> distinct(List<Row> rows, String key) {
        LinkedHashSet<String> set = new LinkedHashSet<>();
        for (Row r : rows) {
            String v = r.get(key);
            if (v != null) {
                set.add(v);
            }
        }
        return new ArrayList<>(set);
    }

    private static Path jmhResultsDir() {
        Path base = Path.of("").toAbsolutePath();
        Path metrics = base.resolve("metrics");
        if (!Files.exists(metrics) && base.getParent() != null) {
            metrics = base.getParent().resolve("metrics");
        }
        return metrics.resolve("jmh-results");
    }

    private record Row(Map<String, String> cells) {
        String get(String key) {
            return cells.get(key);
        }

        boolean has(String key) {
            return cells.containsKey(key);
        }
    }
}
